/* Frontend journey views and a timed UI simulation. No network or model calls. */
const simulationTimers = new Map();
const TASK_DURATION_MS = 3000;
const taskLabels = {PENDING:'Đang chờ',ASSESSING:'Đánh giá độc lập',REVIEWING:'Phản biện',SYNTHESIZING:'Tổng hợp',DONE:'Hoàn tất',FAILED:'Dừng tại đây',SKIPPED:'Chưa thực hiện'};
function backButton(page,label){return btn(ico('back')+' '+label,'navigate','small back-link',`data-page="${page}"`);}
function openExpert(id,editing=false){state.expertId=id||null;state.expertEditing=editing||!id;state.expertDraft=id?clone(expertById(id)):{role:'',domain:'AI & Data',approach:'',prompt:'',skills:[]};go('expert');}
function renderExpertPage(){
  const e=state.expertDraft;
  const back=backButton('experts','Quay lại danh sách expert');
  if(state.expertEditing)return `${back}${heading('EXPERT / '+(state.expertId?'EDIT':'CREATE'),state.expertId?'Điều chỉnh chuyên gia AI':'Tạo chuyên gia AI','Định nghĩa một vai trò chuyên môn. Danh tính cá nhân không bắt buộc.')}<form id="expert-form" data-id="${state.expertId||''}" class="expert-editor"><section class="card stack"><h3>Chuyên môn & cách tư duy</h3><div class="field"><label class="label" for="expert-role">Vai trò chuyên môn *</label><input id="expert-role" name="role" data-expert-field="role" required value="${esc(e.role)}" placeholder="Ví dụ: Model Risk Expert"></div><div class="field"><label class="label" for="expert-domain">Lĩnh vực</label><input id="expert-domain" name="domain" data-expert-field="domain" value="${esc(e.domain)}"></div><div class="field"><label class="label" for="expert-approach">Cách đánh giá *</label><textarea id="expert-approach" name="approach" data-expert-field="approach" required placeholder="Expert ưu tiên bằng chứng gì? Lập luận và phản biện theo cách nào?">${esc(e.approach)}</textarea></div><div class="field"><label class="label" for="expert-prompt">System instructions</label><textarea class="prompt-editor" id="expert-prompt" name="prompt" data-expert-field="prompt" placeholder="Phạm vi, nguyên tắc và những điều expert cần tránh…">${esc(e.prompt)}</textarea></div></section><aside class="stack"><section class="card"><h3>Kỹ năng chuyên môn</h3><p class="small muted tiny-gap">Chọn và đọc hướng dẫn ngay tại đây.</p>${skills.map(s=>`<div class="skill-choice"><label class="check"><input type="checkbox" name="skills" data-expert-skill value="${esc(s.name)}" ${e.skills.includes(s.name)?'checked':''}>${esc(s.name)}</label><details><summary>Đọc SKILL.md</summary><pre>${esc(s.content)}</pre></details></div>`).join('')}</section><div class="notice">Knowledge Base chưa triển khai. Expert nhận tài liệu được gán trong từng plan.</div><div class="row">${btn('Hủy','cancel-expert')}<button class="btn primary grow" type="submit">${state.expertId?'Lưu thay đổi':'Tạo expert'}</button></div></aside></form>`;
  return `${back}${heading('EXPERT PROFILE',esc(e.role),'Hồ sơ chuyên môn dùng để cấu hình expert trong plan.',btn(ico('edit')+' Chỉnh sửa expert','edit-expert','primary'))}<div class="expert-profile-layout"><section class="stack"><article class="card expert-summary"><div class="row">${avatar(e)}<div><h2>${esc(e.role)}</h2><div class="row tiny-gap">${badge(e.domain,'purple')}${badge('Role-based expert')}</div></div></div><div class="divider"></div><h3>Cách đánh giá</h3><p class="small muted tiny-gap">${esc(e.approach)}</p></article><article class="card"><div class="between section-title"><h3>System instructions</h3>${badge('Chỉ dẫn chuyên môn')}</div><pre class="profile-prompt">${esc(e.prompt||'Chưa có chỉ dẫn bổ sung.')}</pre></article></section><aside class="stack"><section class="card"><h3>Skills · ${e.skills.length}</h3>${e.skills.map(name=>{const skill=skills.find(s=>s.name===name);return `<details class="profile-skill"><summary>${ico('book')} ${esc(name)}</summary><pre>${esc(skill?.content||'Chưa có nội dung.')}</pre></details>`;}).join('')||'<p class="small muted tiny-gap">Chưa gắn skill.</p>'}</section><section class="notice"><strong>Sử dụng expert</strong><br>Gán expert này vào một hoặc nhiều task trong màn Review plan. Tài liệu và giới hạn trao đổi được đặt theo task.</section></aside></div>`;
}
function renderTemplates(){
  return `${backButton('cases','Quay lại Cases')}${heading('NEW CASE','Bạn muốn bắt đầu như thế nào?','Dùng một plan dựng sẵn để bắt đầu nhanh, hoặc xây dựng discussion từ vấn đề của riêng bạn.')}<section class="open-discussion-entry"><div class="row"><span class="avatar">${ico('chat')}</span><div><h2>Open Discussion</h2><p>Chưa dùng template? Mô tả chủ đề và đầu ra, rồi đi qua 4 bước chuẩn bị.</p></div></div>${btn('Bắt đầu Open Discussion '+ico('arrow'),'open-discussion','primary')}</section><section class="direct-exchange-entry"><div class="row"><span class="avatar purple">${ico('chat')}</span><div><h3>Chỉ cần một góc nhìn chuyên môn?</h3><p>Chọn một expert và trao đổi riêng, không cần thiết lập plan.</p></div></div>${btn('Trực tiếp trao đổi '+ico('arrow'),'choose-direct-expert','subtle','data-from="templates"')}</section><div class="between template-section-heading"><div><div class="eyebrow">READY-TO-USE PLANS</div><h2>Chọn một template</h2></div><span class="small muted">Chọn → Review plan → Chạy</span></div><div class="grid2 template-selection">${templates.map(t=>`<button class="card template-card" data-action="use-template" data-id="${t.id}"><div class="between"><span class="avatar">${ico(t.icon)}</span>${badge(t.tag,'red')}</div><h2>${esc(t.title)}</h2><p>${esc(t.description)}</p><div class="template-route" aria-hidden="true"><span>01</span><i></i><span>02</span><i></i><span>${String(t.steps).padStart(2,'0')}</span><label>${t.steps} tasks có sẵn</label></div><div class="template-includes"><span>${ico('expert')} Expert đã phân công</span><span>${ico('file')} ${esc(t.output)}</span></div><div class="template-footer between"><span>Bỏ qua bước chuẩn bị 1–3</span><span class="template-start">Review plan ${ico('arrow')}</span></div></button>`).join('')}</div>`;
}
function templateInputsModal(tab){
  if(tab==='cases')return openModal('Case tham khảo của plan','Tùy chọn; bổ sung trực tiếp tại bước review.',`<div class="stack">${cases.filter(c=>c.public).map(c=>`<label class="card template-case-choice"><input type="checkbox" data-template-case value="${c.id}" ${state.selectedCases.includes(c.id)?'checked':''}><span><strong class="small">${esc(c.title)}</strong><p class="small muted tiny-gap">${esc(c.description)}</p></span></label>`).join('')}</div><div class="wizard-foot"><span class="small muted">Chỉ dùng case đã được chia sẻ.</span>${btn('Xong','close-modal','primary')}</div>`);
  openModal('Bối cảnh & tài liệu của case','Template đã có plan. Bạn có thể bổ sung đầu vào ngay tại đây.',`<div class="stack">${[['situation','Bối cảnh'],['task','Mục tiêu'],['action','Phương án & ràng buộc'],['result','Kết quả mong muốn']].map(([key,label])=>`<label><span class="label">${label}</span><textarea data-star="${key}">${esc(state.star[key])}</textarea></label>`).join('')}<section><h3>Tài liệu hồ sơ dùng chung</h3>${documents.map(d=>`<label class="check"><input type="checkbox" data-discussion-doc value="${d.id}" ${state.discussionDocs.includes(d.id)?'checked':''}>${esc(d.name)}</label>`).join('')}<label class="label gap" for="document-upload">Thêm tài liệu từ máy</label><input id="document-upload" type="file" accept=".txt,.md,.csv,.pdf,.docx" multiple><p class="small muted tiny-gap">TXT/MD/CSV được đọc cục bộ; PDF/DOCX chỉ hiển thị metadata.</p></section></div><div class="wizard-foot"><span class="small muted">Chỉ áp dụng cho case hiện tại.</span>${btn('Xong','close-modal','primary')}</div>`);
}
function currentGraphView(){return state.page==='running'&&state.run?state.run.dagView:state.dagView;}
function elapsedLabel(ms){const seconds=Math.max(0,Math.round(ms/1000));return seconds<60?seconds+'s':Math.floor(seconds/60)+'m '+seconds%60+'s';}
function traceTime(ms){const seconds=Math.max(0,Math.floor(ms/1000));return String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');}
function simulationTrace(run,type,title,detail,step){run.trace.push({time:traceTime(Date.now()-run.startedAt),type,title,detail,...(step?{step}:{} )});}
function paintSimulation(run){
  if(state.run===run&&state.page==='running')render();
  else if(state.page==='cases'&&state.caseTab==='mine')render();
}
function stopSimulationTimer(run){clearTimeout(simulationTimers.get(run.id));simulationTimers.delete(run.id);}
function finishSimulation(run,exit=null){
  stopSimulationTimer(run);run.status=exit?'incomplete':'completed';run.exit=exit;run.finishedAt=Date.now();run.durationMs=run.finishedAt-run.startedAt;run.activeStep=null;
  if(exit)for(const s of run.plan.steps)if(run.taskStates[s.id]!=='DONE')run.taskStates[s.id]=s.id===exit.step?'FAILED':'SKIPPED';
  simulationTrace(run,run.status,exit?'Thoát sớm · chưa hoàn tất':'Hoàn tất plan',exit?.reason||'Kết quả và bất đồng được giữ nguyên. Chưa được người thật phê duyệt.');
  if(state.run===run&&state.page==='running'){state.dashTab='overview';state.dashboardView='map';state.argumentId=null;state.feedExpert='';state.feedFilter='all';state.argumentView.auto=true;go('dashboard');}else paintSimulation(run);
}
function startSimulation(run){
  stopSimulationTimer(run);run.status='running';run.startedAt=Date.now();run.finishedAt=null;run.durationMs=0;run.results=[];run.trace=[];run.exit=null;run.followActive=true;
  run.taskStates=Object.fromEntries(run.plan.steps.map(s=>[s.id,'PENDING']));run.dagView={zoom:1,x:0,y:0,auto:true};
  const order=topologicalSteps(run.plan.steps);run.selectedStep=order[0]?.id;
  simulationTrace(run,'plan_frozen','Cố định bản plan',`${order.length} task; mỗi task mô phỏng ${TASK_DURATION_MS/1000}s.`);
  if(order.length!==run.plan.steps.length){finishSimulation(run,{step:null,reason:'Không thể sắp xếp phụ thuộc của plan.',completed:[],unexecuted:run.plan.steps.map(s=>s.id)});return;}
  function taskAt(index){
    if(run.status!=='running')return;
    if(index>=order.length){finishSimulation(run);return;}
    const task=order[index];run.activeStep=task.id;if(run.followActive)run.selectedStep=task.id;
    run.taskStates[task.id]='ASSESSING';run.taskStartedAt=Date.now();
    simulationTrace(run,'assessment',task.id+' · Đánh giá độc lập',`${task.experts.length} expert nhận context theo phân công.`,task.id);paintSimulation(run);
    simulationTimers.set(run.id,setTimeout(()=>{
      if(run.status!=='running')return;
      run.taskStates[task.id]=task.experts.length>1&&task.rounds>0?'REVIEWING':'SYNTHESIZING';
      simulationTrace(run,'phase',task.id+' · '+taskLabels[run.taskStates[task.id]],task.experts.length>1?`Phản biện mô phỏng; giới hạn ${task.rounds} vòng.`:'Một expert, không phản biện chéo.',task.id);paintSimulation(run);
      simulationTimers.set(run.id,setTimeout(()=>{
        if(run.status!=='running')return;
        run.taskStates[task.id]='SYNTHESIZING';paintSimulation(run);
        simulationTimers.set(run.id,setTimeout(()=>{
          if(run.status!=='running')return;
          run.taskStates[task.id]='DONE';const result=buildResult(task,index,run);result.durationMs=Date.now()-run.taskStartedAt;run.results.push(result);
          simulationTrace(run,'commit',task.id+' · Hoàn tất & tạo brief',`Đã hoàn tất sau ${elapsedLabel(result.durationMs)}. Giữ kết quả và bất đồng.`,task.id);taskAt(index+1);
        },TASK_DURATION_MS/3));
      },TASK_DURATION_MS/3));
    },TASK_DURATION_MS/3));
  }
  taskAt(0);
}
function finishFixture(scenario){
  const run=state.run;if(!run){toast('Start một discussion trước.');return;}
  stopSimulationTimer(run);run.results=[];run.trace=[];run.startedAt=Date.now();run.taskStates=Object.fromEntries(run.plan.steps.map(s=>[s.id,'PENDING']));
  const order=topologicalSteps(run.plan.steps),count=scenario==='partial'?Math.max(0,Math.min(2,order.length-1)):order.length;
  order.slice(0,count).forEach((s,i)=>{run.taskStates[s.id]='DONE';run.results.push({...buildResult(s,i,run),durationMs:TASK_DURATION_MS});simulationTrace(run,'commit',s.id+' · Hoàn tất (preview)','Kết quả fixture được mở bằng công cụ Prototype.',s.id);});
  run.startedAt=Date.now()-count*TASK_DURATION_MS;
  finishSimulation(run,scenario==='partial'?{step:order[count]?.id||null,reason:'Mô phỏng thoát sớm: task hết ngân sách. Các bước còn lại chưa được thực hiện.',completed:run.results.map(r=>r.stepId),unexecuted:order.slice(count).map(s=>s.id)}:null);
  state.dashTab='overview';go('dashboard');
}
function renderRunning(){
  const run=state.run,active=run.plan.steps.find(s=>s.id===run.activeStep),progress=run.results.length/run.plan.steps.length*100;
  return `<div class="planning-title runtime-title"><div><div class="eyebrow">LIVE RUN · FRONTEND SIMULATION</div><h1>${esc(run.plan.title)}</h1></div><span class="runtime-badge"><span class="pulse"></span> Đang thực hiện</span></div><div class="planning-workspace runtime-workspace"><div class="job-left">${renderDAG({runtime:true})}${renderRuntimeDetails(run)}</div><aside class="card job-info"><header class="job-info-header"><div class="eyebrow">RUN OVERVIEW</div><h3>Tiến trình thực hiện</h3></header><div class="job-info-body" data-scroll="job-info"><div class="between"><strong class="small">${run.results.length} / ${run.plan.steps.length} task hoàn tất</strong><span class="small muted">${Math.round(progress)}%</span></div><div class="progress"><i style="width:${progress}%"></i></div><div class="simulation-clock">${ico('clock')} 3 giây / task <span>Khoảng ${run.plan.steps.length*3} giây cho plan này</span></div><div class="inspector-group"><h3>Đang xử lý</h3><p class="small tiny-gap">${esc(active?.title||'Đang hoàn tất')}</p><div class="row tiny-gap">${badge(taskLabels[run.taskStates[run.activeStep]]||'Đang chạy','red')}</div><p class="small muted tiny-gap">${active?esc(active.output):''}</p></div><div class="inspector-group"><h3>Expert tham gia</h3><div class="runtime-experts">${run.plan.experts.map(e=>`<div class="row tiny-gap">${avatar(e)}<span>${esc(e.role)}</span></div>`).join('')}</div></div><div class="inspector-group"><h3>Sự kiện gần nhất</h3>${run.trace.slice(-3).reverse().map(t=>`<div class="runtime-event"><time>${t.time}</time><p>${esc(t.title)}</p></div>`).join('')}</div><div class="notice gap">Mô phỏng giao diện bằng timer trong trình duyệt. Không gọi model. Khi mọi task hoàn tất, dashboard tự mở.</div></div></aside></div><footer class="planning-footer">${backButton('cases','Quay lại Cases')}<span class="planning-feedback">Bạn có thể rời trang; mô phỏng tiếp tục trong phiên trình duyệt.</span>${btn(ico('graph')+' Theo dõi task đang chạy','follow-task','small')}</footer>`;
}
function renderRuntimeDetails(run){
  const task=run.plan.steps.find(s=>s.id===run.selectedStep)||run.plan.steps[0];if(!task)return '';
  const status=run.taskStates[task.id],result=run.results.find(r=>r.stepId===task.id),current=run.activeStep===task.id;
  const phases=['ASSESSING',...(task.experts.length>1&&task.rounds>0?['REVIEWING']:[]),'SYNTHESIZING','DONE'];
  const phaseIndex=phases.indexOf(status);
  return `<section class="card node-details" id="node-details"><header class="node-detail-header"><div class="row"><span class="task-icon">${ico('plan')}</span><div><h3>${task.id} · ${esc(task.title)}</h3><span class="small muted">${taskLabels[status]||'Đang chờ'} · Chỉ xem</span></div></div>${badge(result?'3s':current?'Đang xử lý':'Chờ phụ thuộc',result?'green':current?'red':'')}</header><div class="node-detail-body" data-scroll="node-details"><div class="runtime-phases">${phases.map((phase,i)=>`<div class="runtime-phase ${phaseIndex>i?'passed':phase===status?'current':''}"><span>${phaseIndex>i?'✓':i+1}</span><label>${taskLabels[phase]}</label></div>`).join('')}</div><div class="grid2 runtime-task-content"><section><h3>Expert được giao</h3><div class="runtime-experts">${task.experts.map(id=>{const e=run.plan.experts.find(e=>e.id===id);return `<div class="row tiny-gap">${avatar(e)}<span>${esc(e?.role||id)}</span></div>`;}).join('')}</div><h3 class="gap">Context đầu vào</h3><p class="small muted tiny-gap">${esc(task.instruction)}</p><p class="small muted tiny-gap">${task.depends.length?'Brief từ '+task.depends.join(', '):'Không có upstream'} · ${task.docs.length} tài liệu riêng · ${task.rounds} vòng tối đa</p></section><section><h3>Đầu ra của task</h3><p class="small muted tiny-gap">${esc(result?.summary||task.output)}</p>${result?`<div class="notice tiny-gap">${esc(result.dissent)}</div>${btn('Ý kiến & bằng chứng '+ico('arrow'),'result-detail','small gap',`data-id="${task.id}"`)}`:`<div class="notice tiny-gap">${current?'Kết quả sẽ xuất hiện sau khi task hoàn tất.':'Task bắt đầu khi các bước phụ thuộc đã hoàn tất.'}</div>`}</section></div></div></section>`;
}
function renderDashboardInsights(run){
  const rated=run.results.filter(r=>r.rating),ratings=['LOW','MODERATE','HIGH','CRITICAL'];
  return `<section class="card dashboard-insights"><div><div class="eyebrow">RUN COMPLETE · SAMPLE OUTPUT</div><h2>${run.status==='completed'?'Từ đánh giá đến kết quả sử dụng được.':'Những gì đã hoàn thành trước khi thoát.'}</h2><p class="small muted tiny-gap">${run.results.length} task đã tạo kết quả · ${elapsedLabel(run.durationMs||0)} mô phỏng · ${run.results.filter(r=>new Set(r.experts.map(e=>e.final)).size>1).length} task còn khác biệt về rating.</p></div><div class="dashboard-distribution">${rated.length?ratings.map(rating=>{const count=rated.filter(r=>r.rating===rating).length;return `<div class="rating-distribution"><span>${rating}</span><div><i class="rating-${rating.toLowerCase()}" style="width:${count/rated.length*100}%"></i></div><strong>${count}</strong></div>`;}).join(''):`<div class="notice">Đầu ra được định nghĩa riêng trong plan. Chưa có rating chuẩn hóa cho dữ liệu mẫu này.</div>`}</div></section>`;
}
